/**
 * Logo de la tienda para el encabezado del comprobante PDF (plan §18.4).
 *
 * `pdfmake` no carga una URL remota de forma fiable y el CSP la bloquearía —
 * por eso va embebido en base64, reducido a un ancho de recibo (270×90 px,
 * generado a partir de `assets/images/logo.png`, el mismo logo aprobado que
 * usan el login y el topbar).
 */
export const RECEIPT_LOGO_BASE64 =
    'data:image/png;base64,';
